<link href="https://fonts.googleapis.com/css2?family=Jost:wght@300;400;500;600;700&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#D5281F;      /* primary red   */
    --blue:#1B4F9B;     /* primary blue  */
    --yellow:#F2B705;   /* primary yellow*/
    --black:#0B0B0B;    /* the dividing line */
    --paper:#FBF7EE;    /* white ground   */
    --ink:#111111;
    --grey:#6E6E6E;
    --rule:#111111;
    --measure:clamp(18px, 2.4vw, 28px);
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{background:var(--paper);color:var(--ink);font-family:'Jost',system-ui,sans-serif;font-weight:400;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
  body{overflow-x:hidden;line-height:1.45}
  a{color:inherit}

  /* ---------- masthead ---------- */
  header{
    display:flex;align-items:center;justify-content:space-between;gap:1rem;
    padding:var(--measure) var(--measure) 0;
    max-width:1180px;margin:0 auto;
  }
  .mark{display:flex;align-items:center;gap:.6rem;font-weight:600;letter-spacing:.02em;font-size:.95rem}
  .mark .swatch{display:inline-flex;width:34px;height:14px;border:2px solid var(--black)}
  .mark .swatch span{flex:1}
  .mark .swatch .r{background:var(--red)}
  .mark .swatch .b{background:var(--blue)}
  .mark .swatch .y{background:var(--yellow)}
  nav ul{list-style:none;display:flex;gap:1.1rem;font-size:.82rem;font-weight:500;letter-spacing:.04em;text-transform:uppercase}
  nav a{text-decoration:none;padding-bottom:2px;border-bottom:2px solid transparent;transition:border-color .18s}
  nav a:hover{border-color:var(--black)}

  /* ---------- hero ---------- */
  .hero{
    display:grid;grid-template-columns:minmax(280px,1fr) minmax(320px,1.15fr);
    gap:clamp(1.5rem,3vw,3rem);
    align-items:center;
    max-width:1180px;margin:0 auto;
    padding:calc(var(--measure)*1.2) var(--measure) calc(var(--measure)*1.6);
  }
  .hero-text .eyebrow{font-size:.8rem;font-weight:600;letter-spacing:.16em;text-transform:uppercase;color:var(--grey);margin-bottom:1.1rem}
  .hero-text h1{font-size:clamp(2rem,4.4vw,3.4rem);font-weight:700;line-height:1.02;letter-spacing:-.01em}
  .hero-text h1 em{font-style:normal;color:var(--red)}
  .hero-text .sub{margin-top:1rem;font-size:1.05rem;font-weight:300;max-width:34ch;color:#2a2a2a}
  .pill-row{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:1.4rem}
  .pill{font-size:.78rem;font-weight:500;letter-spacing:.05em;padding:.34rem .7rem;border:1.5px solid var(--black);text-transform:uppercase;background:transparent}
  .pill.red{background:var(--red);color:#fff;border-color:var(--red)}
  .pill.blue{background:var(--blue);color:#fff;border-color:var(--blue)}
  .pill.yellow{background:var(--yellow);color:#111;border-color:var(--yellow)}

  /* the framed composition */
  .canvas-frame{
    border:6px solid var(--black);
    background:#fff;
    box-shadow:14px 14px 0 -2px rgba(0,0,0,.18);
    position:relative;
    aspect-ratio:4/3;
    max-width:520px;
    margin-left:auto;
  }
  .canvas-frame canvas{display:block;width:100%;height:100%}
  .canvas-caption{
    position:absolute;left:0;bottom:-1.9rem;font-size:.74rem;letter-spacing:.08em;text-transform:uppercase;color:var(--grey);font-weight:500
  }

  /* ---------- sections ---------- */
  main{max-width:1180px;margin:0 auto;padding:0 var(--measure) calc(var(--measure)*2)}
